sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	var areAnyCorrect = new GlideAjax("QuizHelper");
    areAnyCorrect.addParam('sysparm_name', 'hasCorrect');
    areAnyCorrect.addParam('sysparm_sys_id', g_form.getUniqueValue());
    areAnyCorrect.addParam('sysparm_question', g_form.getValue("question"));
    areAnyCorrect.getXML(ParseQuizUtil);

    function ParseQuizUtil(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
		var hasCorrect = answer === "true";
		var isCurrentCorrect = g_form.getValue("correct") === "true";
		if (!hasCorrect && !isCurrentCorrect) {
			g_form.addInfoMessage("Questions must have at least one correct answer!");
		} else {
			g_form.clearMessages();
		}
    }

}
